namespace Open.Database.Extensions;

/// <summary>
/// Base class for developing expressive commands.
/// Includes methods for use with IDbConnection and IDbCommand types.
/// </summary>
/// <typeparam name="TConnection">The type of the connection to be used.</typeparam>
/// <typeparam name="TCommand">The type of the commands generated by the connection.</typeparam>
/// <typeparam name="TReader">The type of reader created by the command.</typeparam>
/// <typeparam name="TDbType">The DB type enum to use for parameters.</typeparam>
/// <typeparam name="TThis">The type of this class in order to facilitate proper expressive notation.</typeparam>
public abstract partial class ExpressiveCommandBase<TConnection, TCommand, TReader, TDbType, TThis>
		: IExecuteCommand<TCommand>, IExecuteReader<TReader>
		where TConnection : class, IDbConnection
		where TCommand : class, IDbCommand
		where TReader : class, IDataReader
		where TDbType : struct
		where TThis : ExpressiveCommandBase<TConnection, TCommand, TReader, TDbType, TThis>
{
	/// <summary>
	/// Utility for simplifying param concatenation.
	/// </summary>
	/// <typeparam name="T">The type of the enumerable.</typeparam>
	/// <param name="first">The first value.</param>
	/// <param name="remaining">The remaining values.</param>
	protected static IEnumerable<T> Concat<T>(T first, ICollection<T> remaining)
		=> CoreExtensions.Concat(first, remaining);

	/// <summary>
	/// The connection provider to used to acquire connections.
	/// </summary>
	protected IDbConnectionPool<TConnection> ConnectionProvider
		=> _poolOrConnection as IDbConnectionPool<TConnection> ?? (EnsureOptions().Provider ??= DbConnectionProvider.Create((TConnection)_poolOrConnection));

	// Either the pool to take connections from, or (a command built from a bare connection) the connection
	// itself: running it needs no pool wrapper object.
	readonly object _poolOrConnection;
	int _busy;

	// The rarely-set members live in a block that is only allocated when one is set, so the usual
	// conn.Command(sql) object stays small (it is allocated on every call).
	private protected sealed class CommandOptions
	{
		public IDbTransaction? Transaction;
		public IDbConnectionPool<TConnection>? Provider;
		public CancellationToken CancellationToken;
		public ushort Timeout = CommandTimeout.DEFAULT_SECONDS;
		public bool UseAsyncRead;

		// Set while a parameter added by AddParam(value) is still waiting for its name to be resolved.
		public bool HasDerivedParams;
	}

	private protected CommandOptions? _options;
	private protected CommandOptions EnsureOptions() => _options ??= new();

	/// <summary>
	/// The transaction to execute commands on if not using a connection factory.
	/// </summary>
	protected IDbTransaction? Transaction => _options?.Transaction;

	/// <summary>Constructs a <see cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}"/>.</summary>
	/// <param name="connectionPool">The pool to acquire connections from.</param>
	/// <param name="type">The command type.</param>
	/// <param name="command">The SQL command.</param>
	/// <param name="params">The list of params</param>
	protected ExpressiveCommandBase(
		IDbConnectionPool<TConnection> connectionPool,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
	{
		_poolOrConnection = connectionPool ?? throw new ArgumentNullException(nameof(connectionPool));
		Command = command ?? throw new ArgumentNullException(nameof(command));
		if (string.IsNullOrWhiteSpace(command)) throw new ArgumentException("Cannot be null or whitespace.", nameof(command));
		Contract.EndContractBlock();

		Type = type;
		if (@params is not null) _params = @params.ToList();
	}

	/// <summary>Constructs a <see cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}"/>.</summary>
	/// <param name="connFactory">The factory to generate connections from.</param>
	/// <param name="type">The command type.</param>
	/// <param name="command">The SQL command.</param>
	/// <param name="params">The list of params</param>
	protected ExpressiveCommandBase(
		IDbConnectionFactory<TConnection> connFactory,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
		: this((connFactory ?? throw new ArgumentNullException(nameof(connFactory))).AsPool(), type, command, @params)
	{
	}

	/// <inheritdoc cref="ExpressiveCommandBase(IDbConnectionFactory{TConnection}, CommandType, string, IEnumerable{Param}?)"/>
	protected ExpressiveCommandBase(
		Func<TConnection> connFactory,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
		: this((connFactory ?? throw new ArgumentNullException(nameof(connFactory))).AsPool(), type, command, @params)
	{
	}

	/// <summary>Constructs a <see cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}"/>.</summary>
	/// <param name="connection">The connection to execute the command on.</param>
	/// <param name="transaction">The optional transaction to execute the command on.</param>
	/// <param name="type">The command type.</param>
	/// <param name="command">The SQL command.</param>
	/// <param name="params">The list of params</param>
	protected ExpressiveCommandBase(
		TConnection connection,
		IDbTransaction? transaction,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
	{
		_poolOrConnection = connection ?? throw new ArgumentNullException(nameof(connection));
		if (transaction is not null) EnsureOptions().Transaction = transaction;
		Command = command ?? throw new ArgumentNullException(nameof(command));
		if (string.IsNullOrWhiteSpace(command)) throw new ArgumentException("Cannot be null or whitespace.", nameof(command));
		Contract.EndContractBlock();

		Type = type;
		if (@params is not null) _params = @params.ToList();
	}

	/// <summary>Constructs a <see cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}"/>.</summary>
	/// <param name="connection">The connection to execute the command on.</param>
	/// <param name="type">The command type.</param>
	/// <param name="command">The SQL command.</param>
	/// <param name="params">The list of params</param>
	protected ExpressiveCommandBase(
		TConnection connection,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
		: this(connection, null, type, command, @params)
	{
	}

	/// <summary>Constructs a <see cref="ExpressiveCommandBase{TConnection, TCommand, TReader, TDbType, TThis}"/>.</summary>
	/// <param name="transaction">The optional transaction to execute the command on.</param>
	/// <param name="type">The command type.</param>
	/// <param name="command">The SQL command.</param>
	/// <param name="params">The list of params</param>
	protected ExpressiveCommandBase(
		IDbTransaction transaction,
		CommandType type,
		string command,
		IEnumerable<Param>? @params)
		: this(
			(TConnection)(transaction ?? throw new ArgumentNullException(nameof(transaction))).Connection!,
			transaction, type, command, @params)
	{
	}

	/// <summary>
	/// The command text or procedure name to use.
	/// </summary>
	public string Command { get; set; }

	/// <summary>
	/// The command type.
	/// </summary>
	public CommandType Type { get; set; }

	/// <summary>
	/// The list of params to apply to the command before execution.
	/// </summary>
	public List<Param> Params => _params ??= [];

	// Most commands have no params, so the list is only created when one is added.
	List<Param>? _params;

	/// <summary>
	/// The command timeout value.
	/// </summary>
	public ushort Timeout
	{
		get => _options?.Timeout ?? CommandTimeout.DEFAULT_SECONDS;
		set
		{
			if (value == CommandTimeout.DEFAULT_SECONDS && _options is null) return;
			EnsureOptions().Timeout = value;
		}
	}

	/// <summary>
	/// Creates the expected command type from the connection provided.
	/// </summary>
	/// <param name="connection">The connection to create the command from.</param>
	/// <returns>The new command to use.</returns>
	protected TCommand PrepareCommand(TConnection connection)
	{
		IDbCommand cmd = connection.CreateCommand(Type, Command, Timeout);
		if (cmd is not TCommand c)
			throw new InvalidCastException($"Actual command type ({cmd.GetType()}) is not compatible with expected command type ({typeof(TCommand)}).");
		if (Transaction != null)
			c.Transaction = Transaction;
		if (_params is { Count: > 0 }) AddParams(c);
		return c;
	}

	/// <summary>
	/// The optional cancellation token to use with supported methods.
	/// </summary>
	public CancellationToken CancellationToken
	{
		get => _options?.CancellationToken ?? CancellationToken.None;
		set
		{
			if (!value.CanBeCanceled && _options is null) return;
			EnsureOptions().CancellationToken = value;
		}
	}

	CancellationToken IExecuteReader.CancellationToken => CancellationToken;

	/// <summary>
	/// Sets the cancellation token.
	/// </summary>
	public TThis UseCancellationToken(CancellationToken token)
	{
		CancellationToken = token;
		return (TThis)this;
	}

	#region AddParam

	/// <summary>
	/// Shortcut to add a parameter to the params list.
	/// </summary>
	protected TThis AddParam(Param param)
	{
		Params.Add(param);
		return (TThis)this;
	}

	/// <summary>
	/// Adds a parameter to the params list.
	/// </summary>
	/// <param name="name">The name of the parameter.</param>
	/// <param name="value">The value of the parameter.</param>
	/// <param name="type">The database type of the parameter.</param>
	/// <param name="direction">The direction of the parameter.</param>
	/// <returns>This instance for use in method chaining.</returns>
	/// <exception cref="ArgumentNullException"><paramref name="name"/> is null.</exception>
	/// <exception cref="ArgumentException"><paramref name="name"/> is blank.</exception>
	public TThis AddParam(string name, object value, TDbType type, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, value, type, direction));

	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, object? value, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, value, null, direction));

	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam<T>(string name, T? value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		where T : struct
		=> AddParam(new(name, value, type, direction));

	// A literal 0 converts implicitly to any enum, so without these a call like AddParam("id", 0) would bind to
	// the type-only or direction-only overloads below and silently add a parameter with no value.
	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, int value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, value, type, direction));

	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, long value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, value, type, direction));

	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, string? value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, value, type, direction));

	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, TDbType type, ParameterDirection direction = ParameterDirection.Input)
		=> AddParam(new(name, null, type, direction));

	// The direction is required so that a single argument never binds here: AddParam(filter.Name) with a string argument must reach AddParam<T>(T value, ...) below, not be read as a parameter name.
	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddParam(string name, ParameterDirection direction)
		=> AddParam(new(name, null, null, direction));

	/// <summary>
	/// Adds an input parameter whose name is taken from the argument expression: <c>AddParam(filter.CompanySerialNum)</c> adds a parameter named for <c>CompanySerialNum</c>.
	/// </summary>
	/// <remarks>
	/// <para>The argument must be a variable or a chain of member accesses (properties and fields alike): <c>startDate</c>, <c>filter.CompanySerialNum</c>, <c>order.Customer.Id</c>.
	/// Anything else (a call, an index, an operator, a literal) throws <see cref="ArgumentException"/>: use <see cref="AddParam(string, object?, ParameterDirection)"/> and name the parameter.</para>
	/// <para>The name is settled when the command executes. For a stored procedure the provider is asked for the procedure's real parameter names, and the argument is matched to one of them:
	/// exactly, else ignoring case, else ignoring case and underscores, so <c>CompanySerialNum</c> finds <c>@company_serial_num</c>. A chain tries its more specific endings first:
	/// <c>order.Customer.Id</c> tries <c>orderCustomerId</c>, <c>CustomerId</c>, then <c>Id</c>. A name that matches nothing throws <see cref="InvalidOperationException"/> listing what the procedure expects.
	/// Where the real names are not available (a text command, or a provider that does not supply them) the last member is used as written.</para>
	/// </remarks>
	/// <typeparam name="T">The type of the value.</typeparam>
	/// <param name="value">The value of the parameter. A <see langword="null"/> is sent as a database null.</param>
	/// <param name="expression">The text of the argument, supplied by the compiler. Do not pass it.</param>
	/// <returns>This instance for use in method chaining.</returns>
	/// <exception cref="ArgumentException">A parameter name cannot be derived from the argument.</exception>
	[OverloadResolutionPriority(-1)]
	public TThis AddParam<T>(T value, [CallerArgumentExpression(nameof(value))] string? expression = null)
		=> AddDerivedParam(value, expression);

	/// <summary>
	/// Conditionally adds an input parameter whose name is taken from the argument expression. See <see cref="AddParam{T}(T, string?)"/>.
	/// </summary>
	/// <typeparam name="T">The type of the value.</typeparam>
	/// <param name="condition">The condition to add the param by.  Only adds if true.</param>
	/// <param name="value">The value of the parameter.</param>
	/// <param name="expression">The text of the argument, supplied by the compiler. Do not pass it.</param>
	/// <returns>This instance for use in method chaining.</returns>
	/// <exception cref="ArgumentException">A parameter name cannot be derived from the argument (checked even when <paramref name="condition"/> is false).</exception>
	[OverloadResolutionPriority(-1)]
	public TThis AddParamIf<T>(bool condition, T value, [CallerArgumentExpression(nameof(value))] string? expression = null)
		=> condition ? AddDerivedParam(value, expression) : CheckDerivable(expression);

	TThis AddDerivedParam(object? value, string? expression)
	{
		if (!ParameterNames.IsDerivable(expression))
			throw NotDerivable(expression);

		// Name is the last member as written; the real name replaces it at execution when the procedure's names are known.
		Params.Add(Param.Derived(ParameterNames.LastMember(expression!), expression!, value));
		EnsureOptions().HasDerivedParams = true;
		return (TThis)this;
	}

	TThis CheckDerivable(string? expression)
		=> ParameterNames.IsDerivable(expression) ? (TThis)this : throw NotDerivable(expression);

	static ArgumentException NotDerivable(string? expression)
		=> new($"Cannot derive a parameter name from the argument '{expression}'. Pass a variable or a chain of members such as filter.CompanySerialNum, or name the parameter: AddParam(\"name\", value).", "value");

	/// <summary>
	/// Adds a return parameter to the params list.
	/// </summary>
	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)"/>
	public TThis AddReturnParam(string name, TDbType type)
		=> AddParam(new(name, null, type, ParameterDirection.ReturnValue));

	/// <inheritdoc cref="AddReturnParam(string, TDbType)"/>
	public TThis AddReturnParam(string name)
		=> AddParam(new(name, null, null, ParameterDirection.ReturnValue));

	/// <summary>
	/// Conditionally adds a parameter to the params list.
	/// </summary>
	/// <param name="condition">The condition to add the param by.  Only adds if true.</param>
	/// <param name="name">The name of the parameter.</param>
	/// <param name="value">The value of the parameter.</param>
	/// <param name="type">The database type of the parameter.</param>
	/// <param name="direction">The direction of the parameter.</param>
	/// <inheritdoc cref="AddParam(string, object, TDbType, ParameterDirection)" path="/*[not(self::param)]"/>
	public TThis AddParamIf(bool condition, string name, object value, TDbType type, ParameterDirection direction = ParameterDirection.Input)
		=> condition ? AddParam(name, value, type, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf<T>(bool condition, string name, T? value, ParameterDirection direction = ParameterDirection.Input)
		where T : struct
		=> condition ? AddParam(name, value, null, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf(bool condition, string name, object? value, ParameterDirection direction = ParameterDirection.Input)
		=> condition ? AddParam(name, value, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf<T>(bool condition, string name, T? value, TDbType? type, ParameterDirection direction = ParameterDirection.Input)
		where T : struct
		=> condition ? AddParam(name, value, type, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf(bool condition, string name, int value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		=> condition ? AddParam(name, value, type, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf(bool condition, string name, long value, TDbType? type = null, ParameterDirection direction = ParameterDirection.Input)
		=> condition ? AddParam(name, value, type, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf(bool condition, string name, TDbType type, ParameterDirection direction = ParameterDirection.Input)
		=> condition ? AddParam(name, type, direction) : (TThis)this;

	/// <inheritdoc cref="AddParamIf(bool, string, object, TDbType, ParameterDirection)"/>
	public TThis AddParamIf(bool condition, string name, ParameterDirection direction)
		=> condition ? AddParam(name, direction) : (TThis)this;

	/// <summary>
	/// Handles adding the list of parameters to a new command.
	/// </summary>
	/// <param name="command">The command to add parameters to.</param>
	protected abstract void AddParams(TCommand command);
	#endregion

	/// <summary>
	/// Sets the timeout value.
	/// </summary>
	/// <param name="seconds">The number of seconds to wait before the connection times out.</param>
	/// <returns>This instance for use in method chaining.</returns>
	public TThis SetTimeout(ushort seconds)
	{
		Timeout = seconds;
		return (TThis)this;
	}

	#region Derived parameter names

	/// <summary>
	/// Gets the names of the parameters a stored procedure declares, so a parameter added with <c>AddParam(value)</c> can be matched to the real one.
	/// A provider that can look this up overrides it; the default returns nothing, and the last member of each argument is used as written.
	/// </summary>
	/// <param name="connection">An open connection to run the lookup on. A command that executes inside a transaction must use <see cref="Transaction"/>.</param>
	/// <param name="procedure">The procedure name as given to the command.</param>
	/// <returns>The names as the provider reports them (a leading <c>@</c> is fine), or an empty or default array when they are not known.</returns>
	protected virtual ImmutableArray<string> GetProcedureParameterNames(TConnection connection, string procedure)
		=> default;

	/// <summary>The asynchronous twin of <see cref="GetProcedureParameterNames"/>.</summary>
	/// <param name="connection">An open connection to run the lookup on.</param>
	/// <param name="procedure">The procedure name as given to the command.</param>
	/// <param name="cancellationToken">The command's cancellation token.</param>
	/// <returns>The names as the provider reports them, or an empty or default array when they are not known.</returns>
	protected virtual ValueTask<ImmutableArray<string>> GetProcedureParameterNamesAsync(TConnection connection, string procedure, CancellationToken cancellationToken)
		=> new(GetProcedureParameterNames(connection, procedure));

	// Runs after the connection is open and before the command is built, once per command: it replaces the provisional names with the real ones.
	void ResolveDerivedParams(TConnection connection)
	{
		if (_options is not { HasDerivedParams: true }) return;

		ImmutableArray<string> names = default;
		if (Type == CommandType.StoredProcedure)
		{
			string key = ProcedureKey(connection);
			if (!ProcedureNameCache.TryGet(NameCacheOwner, key, out names))
			{
				names = GetProcedureParameterNames(connection, Command);
				if (!names.IsDefaultOrEmpty) ProcedureNameCache.Set(NameCacheOwner, key, names);
			}
		}

		ApplyDerivedNames(names);
	}

	async ValueTask ResolveDerivedParamsAsync(TConnection connection)
	{
		ImmutableArray<string> names = default;
		if (Type == CommandType.StoredProcedure)
		{
			string key = ProcedureKey(connection);
			if (!ProcedureNameCache.TryGet(NameCacheOwner, key, out names))
			{
				names = await GetProcedureParameterNamesAsync(connection, Command, CancellationToken).ConfigureAwait(false);
				if (!names.IsDefaultOrEmpty) ProcedureNameCache.Set(NameCacheOwner, key, names);
			}
		}

		ApplyDerivedNames(names);
	}

	// Remembered names belong to the object commands take connections from: a factory (not the wrapper made around it for each command), a pool, or the bare connection.
	object NameCacheOwner => _poolOrConnection switch
	{
		DbConnectionFactoryExtensions.ConnectionFactoryToPoolAdapter<TConnection> typed => typed.Identity,
		DbConnectionFactoryExtensions.ConnectionFactoryToPoolAdapter untyped => untyped.Identity,
		_ => _poolOrConnection,
	};

	// The database is part of the key: one connection can be switched to another database, where the same procedure name may be a different procedure.
	string ProcedureKey(TConnection connection) => connection.Database + "\n" + Command;

	void ApplyDerivedNames(ImmutableArray<string> real)
	{
		List<Param> list = Params;
		for (int i = 0; i < list.Count; i++)
		{
			Param p = list[i];
			if (p.Expression is not { } expression) continue;

			// Without the real names the last member is used as written.
			string name = real.IsDefaultOrEmpty
				? p.Name
				: ParameterNames.Match(ParameterNames.Candidates(expression), real) ?? throw NoMatch(expression, real);

			list[i] = new Param(name, p.Value, p.Type, p.Direction);
		}

		// Two arguments that resolve to one parameter would silently overwrite each other.
		for (int i = 0; i < list.Count; i++)
		{
			for (int j = i + 1; j < list.Count; j++)
			{
				if (string.Equals(BareName(list[i].Name), BareName(list[j].Name), StringComparison.OrdinalIgnoreCase))
					throw new InvalidOperationException($"Two parameters resolve to '{list[i].Name}'. Name one of them explicitly: AddParam(\"name\", value).");
			}
		}

		_options!.HasDerivedParams = false;
	}

	static string BareName(string name) => name.Length > 0 && name[0] == '@' ? name.Substring(1) : name;

	InvalidOperationException NoMatch(string expression, ImmutableArray<string> real)
		=> new($"The argument '{expression}' matches none of the parameters of '{Command}' (tried {string.Join(", ", ParameterNames.Candidates(expression))}). The procedure declares: {string.Join(", ", real)}. Name the parameter explicitly: AddParam(\"name\", value).");

	#endregion

	#region Execution core

	// Every execution path funnels through these two methods: take the connection, make sure it is open,
	// build the command, run the caller's function, release the connection. The caller's inputs travel in
	// TState (a value type for the typed paths) and the functions are static lambdas, so a call allocates
	// no closures or delegates of its own.

	// Open MUST occur before command creation as some DbCommands require it.
	private protected TResult ExecuteCore<TState, TResult>(TState state, Func<TCommand, ConnectionState, TState, TResult> func)
	{
		if (_poolOrConnection is TConnection single)
			return ExecuteDirect(single, state, func);

		var pool = (IDbConnectionPool<TConnection>)_poolOrConnection;
		TConnection conn = pool.Take();
		try
		{
			ConnectionState prior = conn.EnsureOpen();
			ResolveDerivedParams(conn);
			using TCommand cmd = PrepareCommand(conn);
			return func(cmd, prior, state);
		}
		finally
		{
			pool.Give(conn);
		}
	}

	private protected async ValueTask<TResult> ExecuteCoreAsync<TState, TResult>(TState state, Func<TCommand, ConnectionState, TState, ValueTask<TResult>> func)
	{
		CancellationToken.ThrowIfCancellationRequested(); // Since cancelled awaited tasks throw, we will follow the same pattern here.

		if (_poolOrConnection is TConnection single)
		{
			EnterDirect();
			ConnectionState before = single.State;
			try
			{
				ConnectionState prior = await OpenIfNeededAsync(single, CancellationToken).ConfigureAwait(false);
				if (_options is { HasDerivedParams: true }) await ResolveDerivedParamsAsync(single).ConfigureAwait(false);
				using TCommand cmd = PrepareCommand(single);
				return await func(cmd, prior, state).ConfigureAwait(false);
			}
			finally
			{
				ExitDirect(single, before);
			}
		}

		var pool = (IDbConnectionPool<TConnection>)_poolOrConnection;
		TConnection conn = pool.Take();
		try
		{
			ConnectionState prior = await OpenIfNeededAsync(conn, CancellationToken).ConfigureAwait(false);
			if (_options is { HasDerivedParams: true }) await ResolveDerivedParamsAsync(conn).ConfigureAwait(false);
			using TCommand cmd = PrepareCommand(conn);
			return await func(cmd, prior, state).ConfigureAwait(false);
		}
		finally
		{
			pool.Give(conn);
		}
	}

	// An open connection (the usual case) needs no awaiting at all.
	static ValueTask<ConnectionState> OpenIfNeededAsync(TConnection connection, CancellationToken cancellationToken)
	{
		ConnectionState state = connection.State;
		return (state & (ConnectionState.Open | ConnectionState.Broken)) == ConnectionState.Open
			? new ValueTask<ConnectionState>(state)
			: connection.EnsureOpenAsync(cancellationToken);
	}

	TResult ExecuteDirect<TState, TResult>(TConnection single, TState state, Func<TCommand, ConnectionState, TState, TResult> func)
	{
		EnterDirect();
		ConnectionState before = single.State;
		try
		{
			ConnectionState prior = single.EnsureOpen();
			ResolveDerivedParams(single);
			using TCommand cmd = PrepareCommand(single);
			return func(cmd, prior, state);
		}
		finally
		{
			ExitDirect(single, before);
		}
	}

	// A connection that was closed when taken is closed again when released; one that was open stays open.
	void EnterDirect()
	{
		if (Interlocked.CompareExchange(ref _busy, 1, 0) != 0)
			throw new InvalidOperationException("Concurrent use of a single connection is not supported.");
	}

	void ExitDirect(TConnection connection, ConnectionState before)
	{
		try
		{
			if (before == ConnectionState.Closed) connection.Close();
		}
		finally
		{
			Volatile.Write(ref _busy, 0);
		}
	}

	#endregion

	/// <inheritdoc />
	public void Execute(Action<TCommand> action)
	{
		if (action is null) throw new ArgumentNullException(nameof(action));
		Contract.EndContractBlock();

		ExecuteCore(action, static (cmd, _, a) =>
		{
			a(cmd);
			return false;
		});
	}

	/// <inheritdoc />
	public T Execute<T>(Func<TCommand, T> transform)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteCore(transform, static (cmd, _, f) => f(cmd));
	}

	/// <inheritdoc />
	public virtual ValueTask ExecuteAsync(Func<TCommand, ValueTask> handler)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		CancellationToken.ThrowIfCancellationRequested(); // Thrown synchronously, as before.

		return ValueTaskHelpers.Discard(ExecuteCoreAsync(handler, static async (cmd, _, h) =>
		{
			await h(cmd).ConfigureAwait(false);
			return false;
		}));
	}

	// Completes a ValueTask<T> as a plain ValueTask without allocating when it has already finished.
	/// <inheritdoc />
	public virtual ValueTask<T> ExecuteAsync<T>(Func<TCommand, ValueTask<T>> transform)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		CancellationToken.ThrowIfCancellationRequested(); // Thrown synchronously, as before.

		return ExecuteCoreAsync(transform, static (cmd, _, f) => f(cmd));
	}

	void IExecuteCommand.Execute(Action<IDbCommand> action)
		=> Execute(command => action(command));

	T IExecuteCommand.Execute<T>(Func<IDbCommand, T> transform)
		=> Execute(command => transform(command));

	ValueTask IExecuteCommand.ExecuteAsync(Func<IDbCommand, ValueTask> handler)
		=> ExecuteAsync(command => handler(command));

	ValueTask<T> IExecuteCommand.ExecuteAsync<T>(Func<IDbCommand, ValueTask<T>> transform)
		=> ExecuteAsync(command => transform(command));

	/// <summary>
	/// Validates and properly acquires the expected type of the reader.
	/// </summary>
	/// <typeparam name="TActual">The actual type of the reader.</typeparam>
	/// <param name="reader">The reader to cast.</param>
	/// <returns>The expected reader.</returns>
	protected static TReader EnsureReaderType<TActual>(TActual reader)
		where TActual : IDataReader
		=> reader is TReader r ? r : throw new InvalidCastException($"Expected reader type of ({typeof(TReader)}).  Actual: ({reader.GetType()})");

	/// <inheritdoc />
	public TResult ExecuteReader<TState, TResult>(TState state, Func<IDataReader, TState, TResult> transform, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteCore((state, transform, behavior), static (cmd, prior, s) =>
		{
			CommandBehavior b = prior == ConnectionState.Closed ? s.behavior | CommandBehavior.CloseConnection : s.behavior;
			using IDataReader reader = cmd.ExecuteReader(b);
			return s.transform(reader, s.state);
		});
	}

	/// <inheritdoc />
	public ValueTask<TResult> ExecuteReaderAsync<TState, TResult>(TState state, Func<IDataReader, TState, ValueTask<TResult>> transform, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteCoreAsync((state, transform, behavior, CancellationToken), static async (cmd, prior, s) =>
		{
			CommandBehavior b = prior == ConnectionState.Closed ? s.behavior | CommandBehavior.CloseConnection : s.behavior;
			if (cmd is DbCommand dbCommand)
			{
#if NETSTANDARD2_0
#else
				await
#endif
				using DbDataReader dbReader = await dbCommand.ExecuteReaderAsync(b, s.CancellationToken).ConfigureAwait(false);
				return await s.transform(dbReader, s.state).ConfigureAwait(false);
			}

			using IDataReader reader = cmd.ExecuteReader(b);
			return await s.transform(reader, s.state).ConfigureAwait(false);
		});
	}

	/// <inheritdoc />
	public void ExecuteReader(Action<TReader> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		ExecuteReader(handler, static (reader, h) =>
		{
			h(EnsureReaderType(reader));
			return false;
		}, behavior);
	}

	/// <inheritdoc />
	public T ExecuteReader<T>(Func<TReader, T> transform, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteReader(transform, static (reader, f) => f(EnsureReaderType(reader)), behavior);
	}

	/// <inheritdoc />
	public ValueTask ExecuteReaderAsync(Action<TReader> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ValueTaskHelpers.Discard(ExecuteReaderAsync(handler, static (reader, h) =>
		{
			h(EnsureReaderType(reader));
			return new ValueTask<bool>(false);
		}, behavior));
	}

	/// <inheritdoc />
	public ValueTask<T> ExecuteReaderAsync<T>(Func<TReader, T> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ExecuteReaderAsync(handler, static (reader, h) => new ValueTask<T>(h(EnsureReaderType(reader))), behavior);
	}

	/// <inheritdoc />
	public ValueTask ExecuteReaderAsync(Func<TReader, ValueTask> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ValueTaskHelpers.Discard(ExecuteReaderAsync(handler, static async (reader, h) =>
		{
			await h(EnsureReaderType(reader)).ConfigureAwait(false);
			return false;
		}, behavior));
	}

	/// <inheritdoc />
	public ValueTask<T> ExecuteReaderAsync<T>(Func<TReader, ValueTask<T>> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ExecuteReaderAsync(handler, static (reader, h) => h(EnsureReaderType(reader)), behavior);
	}

